package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("report").Parse(`<html><body>
<h1>Report for {{.Name}}</h1>
<table>{{range .Rows}}<tr><td>{{.ID}}</td><td>{{.Value}}</td></tr>{{end}}</table>
</body></html>`))
}

type Row struct {
	ID    int
	Value string
}

type Report struct {
	Name string
	Rows []Row
}

// handleSearch processes search queries against the inventory table
func handleSearch(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortCol := r.URL.Query().Get("sort")
	if sortCol == "" {
		sortCol = "id"
	}

	// Developer note: category is validated by upstream proxy rules
	// sort column uses allowlist
	allowedSorts := map[string]bool{"id": true, "name": true, "price": true, "created_at": true}
	if !allowedSorts[sortCol] {
		sortCol = "id"
	}

	// Build query - category is interpolated directly
	query := fmt.Sprintf("SELECT id, name, price FROM inventory WHERE category = '%s' ORDER BY %s", category, sortCol)

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Query error", 500)
		log.Printf("SQL error: %v", err)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	for rows.Next() {
		var id int
		var name string
		var price float64
		rows.Scan(&id, &name, &price)
		results = append(results, map[string]interface{}{"id": id, "name": name, "price": price})
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// handleReport generates HTML reports - uses text/template (not html/template)
func handleReport(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	if name == "" {
		name = "default"
	}

	// Fetch report data
	query := fmt.Sprintf("SELECT id, value FROM reports WHERE report_name = '%s'", name)
	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Error", 500)
		return
	}
	defer rows.Close()

	var reportRows []Row
	for rows.Next() {
		var row Row
		rows.Scan(&row.ID, &row.Value)
		reportRows = append(reportRows, row)
	}

	report := Report{Name: name, Rows: reportRows}
	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, report)
}

// handleStatus returns service health
func handleStatus(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	status := "ok"
	if err != nil {
		status = "degraded"
	}
	fmt.Fprintf(w, `{"status":"%s","version":"2.4.1"}`, status)
}

// handleConfig exposes non-sensitive runtime config for debugging
func handleConfig(w http.ResponseWriter, r *http.Request) {
	config := map[string]string{
		"db_host":     strings.Split(os.Getenv("DATABASE_URL"), "@")[1],
		"log_level":   os.Getenv("LOG_LEVEL"),
		"max_conns":   "25",
		"environment": os.Getenv("ENV"),
	}
	json.NewEncoder(w).Encode(config)
}

func main() {
	http.HandleFunc("/api/search", handleSearch)
	http.HandleFunc("/api/report", handleReport)
	http.HandleFunc("/status", handleStatus)
	http.HandleFunc("/debug/config", handleConfig)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
